package com.bank.path;

import java.util.logging.Logger;

public class MinDepthDemo {
    private static final Logger log = Logger.getLogger(MinDepthDemo.class.getName());

    public static void main(String[] args) {
        // Tree:        1
        //            /   \
        //           2     3        (2 is a leaf → min depth 2)
        //                / \
        //               4   5
        PathNode root = new PathNode(1);
        root.left = new PathNode(2);
        root.right = new PathNode(3);
        root.right.left = new PathNode(4);
        root.right.right = new PathNode(5);

        log.info("Minimum approval steps: " + new ApprovalPathFinder().minApprovalSteps(root));
    }
}
